solution.go_counting.zig:
const std = @import("std");

pub const Owner=enum {none,black,white};
pub const Point=struct {x:usize,y:usize};
pub const Territory=struct {owner:Owner,points:[]Point};
pub const Board=struct {
    rows:[]const []const u8,
    pub fn init(rows:[]const []const u8) !Board {
        if(rows.len>0) for(rows) |row| {if(row.len!=rows[0].len)return error.InvalidBoard;for(row) |c| if(c!=' ' and c!='B' and c!='W') return error.InvalidBoard;};
        return .{.rows=rows};
    }
    pub fn territory(self:Board,allocator:std.mem.Allocator,x:isize,y:isize) !Territory {
        const height=self.rows.len;const width=if(height==0) 0 else self.rows[0].len;
        if(x<0 or y<0 or x>=width or y>=height)return error.InvalidCoordinate;
        var points=std.array_list.Managed(Point).init(allocator);errdefer points.deinit();
        if(self.rows[@intCast(y)][@intCast(x)]!=' ')return .{.owner=.none,.points=try points.toOwnedSlice()};
        const visited=try allocator.alloc(bool,width*height);defer allocator.free(visited);@memset(visited,false);
        try points.append(.{.x=@intCast(x),.y=@intCast(y)});visited[@as(usize,@intCast(y))*width+@as(usize,@intCast(x))]=true;
        var border:u2=0;var i:usize=0;
        while(i<points.items.len) : (i+=1) {
            const point=points.items[i];
            const directions=[_][2]isize{.{0,1},.{0,-1},.{1,0},.{-1,0}};
            for(directions) |d| {
                const nx=@as(isize,@intCast(point.x))+d[0];const ny=@as(isize,@intCast(point.y))+d[1];
                if(nx<0 or ny<0 or nx>=width or ny>=height)continue;
                const xx:usize=@intCast(nx);const yy:usize=@intCast(ny);const c=self.rows[yy][xx];
                if(c=='B')border|=1 else if(c=='W')border|=2 else if(!visited[yy*width+xx]) {visited[yy*width+xx]=true;try points.append(.{.x=xx,.y=yy});}
            }
        }
        return .{.owner=switch(border){1=>.black,2=>.white,else=>.none},.points=try points.toOwnedSlice()};
    }
    /// Array indexes follow Owner: none, black, white. Caller frees all three slices.
    pub fn territories(self:Board,allocator:std.mem.Allocator) ![3][]Point {
        var groups=[_]std.array_list.Managed(Point){std.array_list.Managed(Point).init(allocator),std.array_list.Managed(Point).init(allocator),std.array_list.Managed(Point).init(allocator)};
        defer for(&groups) |*group| group.deinit();
        const width=if(self.rows.len==0) 0 else self.rows[0].len;
        const visited=try allocator.alloc(bool,width*self.rows.len);defer allocator.free(visited);@memset(visited,false);
        for(self.rows,0..) |row,y| for(row,0..) |c,x| {
            if(c!=' ' or visited[y*width+x])continue;
            const region=try self.territory(allocator,@intCast(x),@intCast(y));defer allocator.free(region.points);
            for(region.points) |p| visited[p.y*width+p.x]=true;
            try groups[@intFromEnum(region.owner)].appendSlice(region.points);
        };
        var result:[3][]Point=undefined;var n:usize=0;errdefer for(result[0..n]) |group| allocator.free(group);
        for(&groups,0..) |*group,i| {result[i]=try group.toOwnedSlice();n+=1;}
        return result;
    }
};

tests.test_go_counting.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("go_counting.zig");

test "black, white, mixed borders, occupied cells, invalid coordinates" {
    const board=try m.Board.init(&.{"  B  "," B B ","B W B"," W W ","  W  "});
    const black=try board.territory(a,0,1);defer a.free(black.points);try t.expectEqual(m.Owner.black,black.owner);try t.expectEqual(@as(usize,3),black.points.len);
    const white=try board.territory(a,2,3);defer a.free(white.points);try t.expectEqual(m.Owner.white,white.owner);try t.expectEqual(@as(usize,1),white.points.len);
    const mixed=try board.territory(a,1,4);defer a.free(mixed.points);try t.expectEqual(m.Owner.none,mixed.owner);try t.expectEqual(@as(usize,3),mixed.points.len);
    const stone=try board.territory(a,1,1);defer a.free(stone.points);try t.expectEqual(@as(usize,0),stone.points.len);
    try t.expectError(error.InvalidCoordinate,board.territory(a,-1,1));try t.expectError(error.InvalidCoordinate,board.territory(a,5,1));
    try t.expectError(error.InvalidCoordinate,board.territory(a,1,-1));try t.expectError(error.InvalidCoordinate,board.territory(a,1,5));
}
test "aggregate territories on empty and rectangular boards" {
    const board=try m.Board.init(&.{" BW "," BW "});const groups=try board.territories(a);defer for(groups) |g| a.free(g);
    try t.expectEqual(@as(usize,0),groups[0].len);try t.expectEqual(@as(usize,2),groups[1].len);try t.expectEqual(@as(usize,2),groups[2].len);
    const empty=try m.Board.init(&.{" "});const all=try empty.territories(a);defer for(all) |g| a.free(g);
    try t.expectEqual(@as(usize,1),all[0].len);try t.expectEqual(@as(usize,0),all[1].len);try t.expectEqual(@as(usize,0),all[2].len);
    const split=try m.Board.init(&.{" B "});const both=try split.territories(a);defer for(both) |g| a.free(g);try t.expectEqual(@as(usize,2),both[1].len);
}
